for k, sc in SCENES.items():
    assert len(sc['symbols']) <= 8, (k, 'coherence cap is 8 symbols')
    assert len(sc['palette']) == 4, (k, '3 base colours + 1 accent')
    for sy in sc['symbols']:
        assert len(sy['cues']) >= 2, (sy['id'], 'every symbol needs at least two encoding cues')
